#!/usr/bin/env node
/**
 * regen-examples.mjs — regenerates `examples/` from the current HEAD.
 *
 * The files under `examples/` are real output: they are the two tranche #2
 * artifacts for three mainnet contracts, generated by this repository's own
 * CLI. They are committed so that a reader can judge the tool without
 * installing it — which only works if they never drift from the code. This
 * script is how they get refreshed.
 *
 * Usage
 * -----
 *     node scripts/regen-examples.mjs [YYYY-MM-DD]
 *
 * The optional argument is the date stamped on the documents (UTC). Passing a
 * fixed date is what makes a regeneration diffable: without it every run
 * rewrites the header with today's date and the diff drowns in noise. Use the
 * date already in `examples/README.md` when you are only re-rendering, and a
 * new one when you are genuinely re-observing the chain.
 *
 * What it does
 * ------------
 * For each contract id in `CONTRACTS` below, runs
 *
 *     node src/cli.ts artifact <id> --timeout 120 -o examples/
 *
 * ONLINE — the contract id (not a local .wasm path) is what makes the CLI
 * collect the tier-B observation window over `getEvents`. Runs are sequential
 * with a pause between them because the default endpoint
 * (`mainnet.sorobanrpc.com`) is a rate-limited public community RPC.
 *
 * Output is non-deterministic across days by construction: the observation
 * window moves with the chain, so event counts and window sizes change. That
 * is the point of the tier-B numbers, and it is why `examples/README.md`
 * states the date its numbers were taken.
 *
 * Exit code is non-zero if any contract fails to generate.
 */
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";

/**
 * The three curated examples. See `examples/README.md` for why each one is
 * here; the short version is: one with real traffic, one DeFi contract with
 * several threats, and one that shows the honest-gap path.
 */
const CONTRACTS = [
  // closest to submittable of the 18 event-declaring corpus contracts
  "CCR2CH4GQVCZHG7CHFVMNANCK45CU5DVKXZIIITDZQAU3CEJZ7RQH2MQ",
  // the busiest: most threats, most monitors, most distinct topics observed
  "CBBMQBNHB2FYVZYV7VNHOJHUMTFJLR4PUMRVQYNW6RHIKZO2NQMIBUCV",
  // the honest-gap path: a window was collected and holds no event at all
  "CDZY62OKIPJAB4HH44BI6PPYO4NGFQV7INDJH4KU6V6RNNSLCTUX3SCS",
];

/** Seconds of budget for the on-chain observation phase, per contract. */
const TIMEOUT = "120";
/** Pause between runs — the public RPC is shared and rate limited. */
const PAUSE_MS = 4000;

const raiz = resolve(dirname(fileURLToPath(import.meta.url)), "..");

const date = process.argv[2] ?? new Date().toISOString().slice(0, 10);
if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
  console.error(`date must be YYYY-MM-DD, got ${JSON.stringify(date)}`);
  process.exit(1);
}

/** Node has no sleep; this is the shortest one that does not pull a dependency. */
const dormir = (ms) => Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);

console.log(`regenerating examples/ for ${CONTRACTS.length} contracts, stamped ${date} (UTC)\n`);

const resumo = [];
let falhou = false;

for (const [i, id] of CONTRACTS.entries()) {
  console.log(`[${i + 1}/${CONTRACTS.length}] ${id}`);
  const inicio = Date.now();
  const r = spawnSync(
    process.execPath,
    ["src/cli.ts", "artifact", id, "--timeout", TIMEOUT, "--date", date, "-o", "examples"],
    { cwd: raiz, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] },
  );
  const segundos = ((Date.now() - inicio) / 1000).toFixed(0);
  process.stdout.write(r.stdout ?? "");
  process.stderr.write(r.stderr ?? "");

  // A janela observada só aparece no stderr de progresso; é o número que o
  // README dos exemplos precisa citar, então ele sobe para o resumo.
  const janela = (r.stderr ?? "").match(/observed window: (\d+) ledgers \(~([\d.]+) h[^)]*\), (\d+) distinct topics/);
  const veredito = [...(r.stdout ?? "").matchAll(/VALIDATION — ([^:]+): (submittable|NOT submittable[^\n]*)/g)];

  if (r.status !== 0) falhou = true;
  resumo.push({
    id,
    exit: r.status,
    segundos,
    ledgers: janela ? Number(janela[1]) : null,
    horas: janela ? Number(janela[2]) : null,
    topicos: janela ? Number(janela[3]) : null,
    vereditos: veredito.map((v) => `${v[1]}: ${v[2]}`),
  });

  if (i < CONTRACTS.length - 1) dormir(PAUSE_MS);
}

console.log("\n─── summary ───");
for (const s of resumo) {
  console.log(`\n${s.id}`);
  console.log(`  exit ${s.exit} in ${s.segundos}s`);
  console.log(
    s.ledgers === null
      ? "  window: not collected"
      : `  window: ${s.ledgers} ledgers (~${s.horas} h), ${s.topicos} distinct topics observed`,
  );
  for (const v of s.vereditos) console.log(`  ${v}`);
}
console.log(
  `\nDone. Update the date and the tier-B numbers in examples/README.md to match this run (${date}).`,
);

process.exit(falhou ? 1 : 0);
